package com.wipro.spring.config; import org.springframework.context.annotation.ComponentScan; import org.springframework.context.annotation.Configuration; import org.springframework.web.servlet.config.annotation.EnableWebMvc; import org.springframework.web.servlet.config.annotation.WebMvcConfigurer; import org.springframework.web.servlet.config.annotation.ViewControllerRegistry; import org.springframework.web.servlet.view.InternalResourceViewResolver; import org.springframework.context.annotation.Bean; @Configuration @EnableWebMvc @ComponentScan("com.wipro.spring") public class WebConfig implements WebMvcConfigurer { @Bean public InternalResourceViewResolver viewResolver(){InternalResourceViewResolver r=new InternalResourceViewResolver();r.setPrefix("/WEB-INF/views/");r.setSuffix(".jsp");return r;} }